  // Parse into JSON
  const parsed = JSON.parse(cleaned);

  return { json: parsed };
});

// timezone offset in hours (Asia/Manila is UTC+8)
const timeZoneOffset = 8; 

// flatten all schedules from all input items
let output = [];

const data = $('Parse Normalized Schedule JSON').first().json.data;

data.forEach(schedule => {
    const { name, date, start, end } = schedule;

    // create Date objects
    let startDate = new Date(`${date}T${start}:00`);
    let endDate = new Date(`${date}T${end}:00`);

    // handle overnight events
    if (endDate <= startDate) {
        endDate.setDate(endDate.getDate() + 1);
    }

    // apply timezone offset (in hours)
    startDate.setHours(startDate.getHours() + timeZoneOffset);
    endDate.setHours(endDate.getHours() + timeZoneOffset);

    // push ISO-ready schedule
    output.push({
        json: {
            name,
            start: startDate.toISOString(),
            end: endDate.toISOString()
        }
    });
});

return output;

