const input = $input.first().json;

const blocks = input.message.blocks;
const action = input.actions[0].action_id;

// Block IDs to remove entirely
const BLOCKS_TO_REMOVE = new Set([
  "approve_block",
  "edit_block",        // remove input blocks entirely
  "reject_block",
  "automation_footer"  // optional future footer
]);

// 1. Remove all buttons
function removeAllButtons(blocks) {
  return blocks
    .map(block => {
      // Remove accessory buttons
      if (block.accessory?.type === "button") {
        const { accessory, ...rest } = block;
        return rest;
      }

      // Remove button elements inside actions block
      if (block.type === "actions") {
        const nonButtonElements = (block.elements || []).filter(
          el => el.type !== "button"
        );

        return {
          ...block,
          elements: nonButtonElements,
        };
      }

      return block;
    })
    // Remove empty actions blocks
    .filter(block => {
      if (block.type === "actions") {
        return block.elements && block.elements.length > 0;
      }
      return true;
    });
}

// 2. Remove known action/input + automation blocks
function removeUnwantedBlocks(blocks) {
  return blocks.filter(block => {
    // Remove blocks by block_id
    if (BLOCKS_TO_REMOVE.has(block.block_id)) {
      return false;
    }

    // Fallback: remove automation footer by content
    const text = block.text?.text || "";
    const isAutomationFooter =
      text.startsWith("_Automated with this") &&
      text.includes("n8n");

    return !isAutomationFooter;
  });
}

// 3. Add status block for approve/reject/edit_start/edit_submit
function addStatus(blocks, action) {
  let statusText = "";

  if (action === "approve_action") statusText = "✅ *Approved*";
  if (action === "reject_action") statusText = "❌ *Rejected*";
  if (action === "edit_action") statusText = "✏️ *Editing started*";
  if (action === "edit_submit") statusText = "✏️ *Editing submitted*";

  if (!statusText) return blocks;

  return [
    ...blocks,
    {
      type: "context",
      elements: [
        {
          type: "mrkdwn",
          text: statusText,
        },
      ],
    },
  ];
}

// === Pipeline ===
const noButtons = removeAllButtons(blocks);
const cleanedBlocks = removeUnwantedBlocks(noButtons);
const finalBlocks = addStatus(cleanedBlocks, action);

return [
  {
    json: {
      blocks: finalBlocks,
    },
  },
];

